import { LoansController } from "@/modules/loans/controller";
import { createLoanSchema } from "@/modules/loans/schemas";
import {
 success,
 failure
} from "@/common/apiResponse";


const controller =
new LoansController();





export async function GET(){


try{


const loans =
await controller.list();



return success(
 loans
);



}catch(error){


return failure(error);


}


}







export async function POST(
request:Request
){


try{


const body =
await request.json();



console.log(
"NEW LOAN REQUEST:",
body
);




const data =
createLoanSchema.parse(
 body
);




const loan =
await controller.create(
 data
);




return success(
 loan,
 201
);



}catch(error){


console.error(
"CREATE LOAN ERROR:",
error
);



return failure(error);


}



}